package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Payload057Test {
 @Test public void frozenNativePayloadsRetainImpactPositionsRecoveryAndOriginalFailures()throws Exception {
  Path root=Files.createTempDirectory("payload057-native-");System.out.println("PAYLOAD057_NATIVE "+root);var worlds=new WorldLedger(root);var in=Load056Test.input(worlds,"wide",1.9,0);var before=worlds.observe(in.getString("worldId"));byte[] originalWorld=Files.readAllBytes(root.resolve("persistent-worlds/state.json"));var run=Construction054Test.nativeRun(root.resolve("assembly"),worlds.source(before),worlds.preview(in));assertTrue(WorldVerify.verify(run).getBoolean("passed"));assertTrue(Construction051.verifyStructure(run).getBoolean("passed"));Files.writeString(root.resolve("assembly-original.json"),WorldReport.packed(run).toString());
  Path loads=root.resolve("loads"),file=loads.resolve(run.getString("id")+".json");var calls=new AtomicInteger();assertThrows(InterruptedException.class,()->Payload057.evaluate(loads,run,()->calls.incrementAndGet()>=3));var stopped=AgentFiles042.read(file,64_000_000).getJSONObject("data");var first=stopped.getJSONArray("attempts").getJSONObject(0);assertEquals("interrupted",first.getString("status"));assertTrue(first.getJSONArray("rows").length()>0);assertTrue(first.getJSONArray("rows").length()<1440);String preserved=first.toString();Files.writeString(root.resolve("stopped-original.json"),Payload057.original(loads,run).toString());
  var result=Payload057.evaluate(loads,run,()->false);Files.writeString(root.resolve("result.json"),result.toString());Files.writeString(root.resolve("resumed-original.json"),Payload057.original(loads,run).toString());assertTrue(result.getBoolean("complete"));assertTrue(result.getBoolean("repeatable"));assertEquals(7,result.getJSONArray("results").length());assertEquals(15,result.getInt("attempts"));assertEquals(14*1440+first.getJSONArray("rows").length(),result.getInt("totalTicks"));var retained=AgentFiles042.read(file,64_000_000).getJSONObject("data");assertTrue(new JSONObject(preserved).similar(retained.getJSONArray("attempts").getJSONObject(0)));
  int payloads=0;for(Object raw:result.getJSONArray("results")){var r=(JSONObject)raw;var m=r.getJSONObject("metrics");assertEquals(1440,m.getInt("nativeTicks"));assertEquals(120,r.getJSONArray("frames").length());assertTrue(r.getBoolean("repeatAgrees"));if(r.getJSONObject("spec").getString("kind").equals("payload")){payloads++;assertTrue(m.getInt("firstPayloadBeamContactTick")>8);assertTrue(m.getDouble("payloadBeamImpulseNs")>0);assertEquals(-9.81,m.getDouble("meanFreeFallAccelerationMps2"),.2);assertEquals(0,m.getDouble("forceEffortNs"),0);assertTrue(m.getDouble("payloadGravityWorkJ")>0);}else assertEquals(32,m.getDouble("forceEffortNs"),1e-6);}
  assertEquals(4,payloads);assertArrayEquals(originalWorld,Files.readAllBytes(root.resolve("persistent-worlds/state.json")));assertTrue(before.similar(worlds.observe(in.getString("worldId"))));
  JSONObject payload=null;for(Object raw:retained.getJSONArray("attempts")){var a=(JSONObject)raw;if(a.getString("caseId").equals("payload-centre")&&a.getString("status").equals("completed")){payload=a;break;}}assertNotNull(payload);final JSONObject source=payload;
  for(String change:List.of("mass","force","offset","tick","contact","pose")){var a=WorldFrames.copy(source);switch(change){case"mass"->a.getJSONArray("objects").getJSONObject(a.getJSONArray("objects").length()-1).put("massKg",7);case"force"->a.getJSONArray("rows").getJSONArray(0).getJSONArray(1).put(1,-1);case"offset"->a.getJSONArray("rows").getJSONArray(0).getJSONArray(2).put(0,8);case"tick"->a.getJSONArray("rows").remove(3);case"contact"->a.getJSONArray("rows").getJSONArray(0).getJSONArray(4).put(new JSONArray(List.of("invented",Payload057.PAYLOAD,0,1)));case"pose"->a.getJSONArray("nativeInitial").getJSONObject(0).put("initializationPoseWrites",2);}assertThrows(change,IllegalStateException.class,()->Payload057.verify(a,run,a.getJSONObject("spec")));}
  byte[] saved=Files.readAllBytes(file);var d=AgentFiles042.read(file,64_000_000).getJSONObject("data");d.put("sourceRunSha256","0".repeat(64));AgentFiles042.saveChecked(file,d);assertThrows(IllegalStateException.class,()->Payload057.read(loads,run));Files.write(file,saved);assertTrue(result.similar(Payload057.read(loads,run)));
 }
 @Test public void protocolUsesSeparateRealMassesAndDeclaredPositions(){var p=Payload057.protocol();assertEquals(7,p.getJSONArray("cases").length());assertEquals(2,p.getInt("repeats"));assertThrows(IllegalArgumentException.class,()->Payload057.specification("made-up"));var centre=Payload057.specification("payload-centre");assertEquals(1,centre.getDouble("massKg"),0);assertFalse(centre.has("forceN"));assertEquals(-.9,Payload057.specification("force-left").getDouble("halfLengthFraction"),0);}
}
